interface UserRepository {
    String getUserData(int id);
    void addUserData(int id, String name);
    void updateUserData(int id, String name);
    void deleteUserData(int id);
}

class MySQLDatabase implements UserRepository {
    private Map<Integer, String> userData;

    public MySQLDatabase() {
        userData = new HashMap<>();
        userData.put(1, "Alice");
        userData.put(2, "Bob");
        userData.put(3, "Charlie");
    }

    @Override
    public String getUserData(int id) {
        if (userData.containsKey(id)) {
            return "User ID: " + id + ", Name: " + userData.get(id);
        }
        return "User not found";
    }

    @Override
    public void addUserData(int id, String name) {
        if (userData.containsKey(id)) {
            System.out.println("User ID already exists. Use updateUserData to modify.");
        } else {
            userData.put(id, name);
            System.out.println("User added successfully.");
        }
    }

    @Override
    public void updateUserData(int id, String name) {
        if (userData.containsKey(id)) {
            userData.put(id, name);
            System.out.println("User updated successfully.");
        } else {
            System.out.println("User ID does not exist. Use addUserData to add new user.");
        }
    }

    @Override
    public void deleteUserData(int id) {
        if (userData.remove(id) != null) {
            System.out.println("User deleted successfully.");
        } else {
            System.out.println("User ID not found.");
        }
    }
}

class UserService {
    private UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

public void addUser(int id, String data) {
        this.userRepository.addUserData(id, data);
    }

public void updateUser(int id, String data) {
        this.userRepository.updateUserData(id, data);
    }

public String getUser(int id) {
        return userRepository.getUserData(id);
    }
